pub fn answer(command: &str) -> Option<i32> {
    let body = command.strip_prefix("What is ")?;
    let body = body.strip_suffix('?')?;
    let mut tokens = body.split_whitespace();

    let mut acc = parse_number(tokens.next()?)?;

    while let Some(token) = tokens.next() {
        match token {
            "plus" => {
                acc += parse_number(tokens.next()?)?;
            }
            "minus" => {
                acc -= parse_number(tokens.next()?)?;
            }
            "multiplied" => {
                if tokens.next() != Some("by") { return None; }
                acc *= parse_number(tokens.next()?)?;
            }
            "divided" => {
                if tokens.next() != Some("by") { return None; }
                acc /= parse_number(tokens.next()?)?;
            }
            #[cfg(feature = "exponentials")]
            "raised" => {
                if tokens.next() != Some("to") { return None; }
                if tokens.next() != Some("the") { return None; }
                let exp = parse_number(tokens.next()?)?;
                if tokens.next() != Some("power") { return None; }
                acc = acc.pow(exp as u32);
            }
            _ => return None,
        }
    }

    Some(acc)
}

